prompt --application/shared_components/user_interface/templates/region/focus_stage
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(935419919798491167)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TFocusStage #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading" data-amc-msg-on="Focus mode on. Press Escape or the Focus button to return to the page." data-amc-msg-off="Focus mode off.">',
'  <div class="amc-TFocusStage-surface">',
'    <header class="amc-TFocusStage-header">',
'      <span class="amc-TFocusStage-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TFocusStage-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TFocusStage-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'      <button type="button" class="amc-TFocusStage-toggle" aria-pressed="false" aria-describedby="#REGION_STATIC_ID#_heading"><span class="amc-TFocusStage-glyph" aria-hidden="true"></span><span class="amc-TFocusStage-toggleLabel">Focus</span><kbd class="amc-TFocusStage-kbd" aria-hidden="true">Esc</kbd></button>',
'    </header>',
'    <div class="amc-TFocusStage-body">#BODY##SUB_REGIONS#</div>',
'    <footer class="amc-TFocusStage-footer">#PREVIOUS##CLOSE##NEXT#</footer>',
'  </div>',
'  <span class="amc-TFocusStage-status" role="status" aria-live="polite"></span>',
'</section>'))
,p_page_plug_template_name=>'AMC Focus Stage'
,p_internal_name=>'AMC_TPL_FOCUS_STAGE'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-focus-stage.js'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-focus-stage.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Living region template (behaviour-aware). A Focus button in the header puts the region on stage: the script adds a page-level scrim to the document body that ignores the pointer, fades and blurs everything outside the region, lifts the region with a ring and deep shadow, and makes its header, with the Focus button, sticky below any fixed page header so it stays reachable in long forms and reports. Focus mode ends with Escape, the Focus button, a click on the dimmed page, or by tabbing onto the dimmed page; focus is never trapped and stays wherever the user put it. Only one region is on stage at a time and nothing is stored. Popups that APEX adds to the page later, such as report menus, date pickers, LOV and modal dialogs, are not dimmed and do not end focus mode; Escape inside an open combobox (aria-expanded true) is left to that control. The region body is never clipped or transformed. The button is a real button with aria-pressed; entering and leaving are announced through a polite live region. Without JavaScript the region is a plain framed region and the Focus button is hidden. Under reduced motion there are no transitions, but the page is still dimmed. Template options: Focus on input enters focus mode as soon as a form field inside the region gets focus, and after Escape waits until focus leaves the region before it can enter again; Deep dim uses a darker scrim and stronger blur; Stage light adds a primary-colored halo around the region on stage; Icon-only button hides the Focus label visually; No body padding runs reports edge to edge. English UI strings to translate in the template: the button label Focus, the key hint Esc, and the data-amc-msg-on and data-amc-msg-off announcements on the region element. Layering: the scrim uses z-index 50 and the region 52, so page headers with a higher z-index stay above the scrim but are dimmed with the rest of the page; if an ancestor of the region forms its own stacking context, the script lifts that ancestor to z-index 51 and dims its other children instead. JavaScript API: amcTplFocusStage.enter(element), amcTplFocusStage.exit(), amcTplFocusStage.active(); a window event amcfocusstage reports each change.'
);
end;
/
